<script setup lang="ts">import {ref} from 'vue';import * as api from '../api/candidates';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const {data,error}=useResource(api.list,[]);const name=ref('芦汀新增勘测点'),latitude=ref(31.36),longitude=ref(120.62),cost=ref(2),message=ref('');async function submit(){try{await api.create({name:name.value,latitude:latitude.value,longitude:longitude.value,cost:cost.value});refreshResources();message.value=''}catch(e:any){message.value=e.message}}</script><template><PageTitle chapter="03" title="候选点的成本与位置" description="点位来自模拟现场勘测。成本须为正数；可以保留多个相近候选点，让预算推演决定取舍。"/><Notice :error="error||message"/><div class="split-layout"><section class="paper table-scroll"><table><thead><tr><th>候选点</th><th>纬度 / 经度</th><th>万元</th></tr></thead><tbody><tr v-for="c in data" :key="c.id"><td><b>{{c.name}}</b><small>{{c.id}}</small></td><td>{{c.latitude.toFixed(4)}} / {{c.longitude.toFixed(4)}}</td><td>{{c.cost}}</td></tr></tbody></table></section><form v-if="user?.role!=='viewer'" class="paper vertical-form" @submit.prevent="submit"><h2>录入勘测候选点</h2><label>点位名称<input v-model="name"/></label><label>纬度 °N<input v-model.number="latitude" type="number" min="-90" max="90" step=".000001"/></label><label>经度 °E<input v-model.number="longitude" type="number" min="-180" max="180" step=".000001"/></label><label>成本（万元）<input v-model.number="cost" type="number" min=".01" step=".01"/></label><button class="primary">保存候选点</button></form></div></template>
